// Draft remediation pull requests on GitHub (spec §9.4). Requires an explicit human action with tickets:write and a
// GitHub connection whose token has Contents (write) and Pull requests (write) on the repository.
// Sentra edits only the manifest text, opens a *draft* PR, never merges, and never executes repository code
// (no npm/composer/pip install): lockfiles must be regenerated by the repository's own CI, which the PR body states.
import { id, badRequest, notFound, AppError } from '../util.mjs';
import { safeFetch } from '../notify/safe-fetch.mjs';
import { getSecretValue } from './secrets.mjs';
import { audit } from '../audit.mjs';

const MANIFEST = { npm: 'package.json', composer: 'composer.json', pypi: 'requirements.txt', maven: 'pom.xml' };

/** Pure manifest edit. Returns { content, change, note } or throws with an explanation when a bump is insufficient. */
export function bumpManifest(ecosystem, text, pkg, fixed) {
  if (ecosystem === 'npm' || ecosystem === 'composer') {
    const j = JSON.parse(text);
    const sections = ecosystem === 'npm' ? ['dependencies', 'devDependencies', 'optionalDependencies'] : ['require', 'require-dev'];
    for (const s of sections) if (j[s]?.[pkg] != null) { const from = j[s][pkg]; j[s][pkg] = `^${fixed}`; return { content: JSON.stringify(j, null, 2) + '\n', change: `${s}.${pkg}: ${from} → ^${fixed}` }; }
    if (ecosystem === 'npm') { j.overrides = { ...(j.overrides || {}), [pkg]: fixed }; return { content: JSON.stringify(j, null, 2) + '\n', change: `overrides.${pkg} = ${fixed}`, note: `${pkg} is transitive; an npm override forces ${fixed}. Prefer upgrading the parent dependency if it supports ${fixed}, and check compatibility.` }; }
    throw new AppError(422, 'TRANSITIVE_DEPENDENCY', `${pkg} is not a direct Composer requirement; upgrade the parent package that requires it. A simple bump is insufficient.`);
  }
  if (ecosystem === 'pypi') {
    const re = new RegExp(`^(${pkg.replace(/[-_.]/g, '[-_.]')})(\\[[^\\]]*\\])?\\s*(==|>=|~=)\\s*[^\\s;#]+`, 'im');
    if (!re.test(text)) throw new AppError(422, 'NOT_PINNED_HERE', `${pkg} is not pinned in requirements.txt; it is transitive or declared elsewhere.`);
    let from; const content = text.replace(re, (m, n, extras, op) => { from = m; return `${n}${extras || ''}==${fixed}`; });
    return { content, change: `${from} → ${pkg}==${fixed}` };
  }
  if (ecosystem === 'maven') {
    const [g, a] = pkg.split(':');
    const re = new RegExp(`(<dependency>\\s*<groupId>${g.replace(/\./g, '\\.')}</groupId>\\s*<artifactId>${a}</artifactId>\\s*<version>)([^<]+)(</version>)`);
    const m = re.exec(text);
    if (!m) throw new AppError(422, 'NOT_DECLARED_HERE', `${pkg} has no explicit <version> in this pom.xml (managed by a parent/BOM or transitive). Update the BOM or dependencyManagement instead.`);
    if (/^\$\{/.test(m[2])) throw new AppError(422, 'PROPERTY_VERSION', `${pkg} version comes from property ${m[2]}; update that property deliberately.`);
    return { content: text.replace(re, `$1${fixed}$3`), change: `${pkg}: ${m[2]} → ${fixed}` };
  }
  throw new AppError(422, 'ECOSYSTEM_UNSUPPORTED', `Draft PRs are supported for npm, Composer, PyPI (requirements.txt) and Maven (pom.xml); not ${ecosystem}.`);
}

export async function createDraftPr(app, ctx, findingId, { connection_id, manifest_path }) {
  const db = app.db;
  const f = await db.one(`SELECT f.*, c.ecosystem, c.name AS package, a.title AS advisory_title, p.key AS project_key, s.key AS service_key, e.key AS env_key FROM findings f JOIN components c ON c.id=f.component_id JOIN advisories a ON a.id=f.advisory_id JOIN projects p ON p.id=f.project_id LEFT JOIN services s ON s.id=f.service_id LEFT JOIN environments e ON e.id=f.environment_id WHERE f.id=$1 AND f.org_id=$2`, [findingId, ctx.orgId]);
  if (!f) throw notFound('Finding');
  if (!f.fixed_version) throw badRequest('No verified fixed version is recorded for this finding; a draft PR needs a target version.');
  const conn = await db.one(`SELECT * FROM connections WHERE id=$1 AND org_id=$2 AND kind='github'`, [connection_id, ctx.orgId]);
  if (!conn || (conn.project_id && conn.project_id !== f.project_id)) throw notFound('GitHub connection for this project');
  if (['disconnected', 'disabled'].includes(conn.status)) throw new AppError(409, 'CONNECTION_DISCONNECTED', 'Reconnect the GitHub connection first.');
  const token = await getSecretValue(db, conn.org_id, conn.secret_id);
  const base = conn.config.api_base || 'https://api.github.com'; const { owner, repo } = conn.config;
  const net = { allowPrivate: app.cfg.allowPrivateWebhookTargets, allowHttp: app.cfg.allowPrivateWebhookTargets };
  const h = { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28', 'Content-Type': 'application/json', 'User-Agent': 'Sentra' };
  const gh = async (method, path, body) => { const r = await safeFetch(`${base}/repos/${owner}/${repo}${path}`, { method, headers: h, body: body ? JSON.stringify(body) : undefined }, net); if (!r.ok) throw new AppError(502, 'GITHUB_ERROR', `GitHub ${method} ${path} → ${r.status}: ${r.text.slice(0, 200)}`); return r.json(); };
  const path = manifest_path || MANIFEST[f.ecosystem];
  if (!path || path.includes('..')) throw badRequest('manifest_path is required for this ecosystem.');
  const pkgName = f.ecosystem === 'maven' ? f.package : f.package;
  const repoInfo = await gh('GET', '');
  const baseBranch = repoInfo.default_branch;
  const ref = await gh('GET', `/git/ref/heads/${encodeURIComponent(baseBranch)}`);
  const file = await gh('GET', `/contents/${path.split('/').map(encodeURIComponent).join('/')}?ref=${encodeURIComponent(baseBranch)}`);
  const current = Buffer.from(file.content || '', 'base64').toString('utf8');
  const bump = bumpManifest(f.ecosystem, current, pkgName, f.fixed_version);
  const branch = `sentra/fix-${pkgName.replace(/[^\w.-]+/g, '-')}-${f.fixed_version}`.slice(0, 120);
  await gh('POST', '/git/refs', { ref: `refs/heads/${branch}`, sha: ref.object.sha });
  await gh('PUT', `/contents/${path.split('/').map(encodeURIComponent).join('/')}`, { message: `fix(deps): ${pkgName} → ${f.fixed_version} (${f.advisory_id})`, content: Buffer.from(bump.content).toString('base64'), sha: file.sha, branch });
  const body = [
    `Remediation for **${f.advisory_id}** (${f.advisory_title || ''}) in \`${pkgName}\` ${f.observed_version || ''} → ${f.fixed_version}.`,
    `Scope: ${f.project_key} / ${f.service_key || 'asset'} / ${f.env_key || '-'} · priority ${f.priority}.`, '',
    `Change: \`${bump.change}\` in \`${path}\`.`, bump.note ? `\n> ${bump.note}\n` : '',
    '**Before merging**', '- Regenerate the lockfile in CI (Sentra does not run package managers or repository scripts).', '- Run the full test suite and the Sentra CI gate on the rebuilt artifact.', '- Review the upstream changelog for breaking changes.', '',
    '**Rollout and rollback**', '- Deploy to UAT, then production, and record each deployment; Sentra verifies the deployed digest before closing the finding.', '- Rollback: redeploy the previous digest. The finding reopens automatically if the vulnerable version returns.', '',
    'This PR was opened as a draft by Sentra on request of an authorized user. Merging it does not close the finding.', '', `Sentra-Finding: ${f.id}`,
  ].join('\n');
  const pr = await gh('POST', '/pulls', { title: `[Sentra] ${pkgName} → ${f.fixed_version} (${f.advisory_id})`, head: branch, base: baseBranch, body, draft: true });
  await db.query(`INSERT INTO pull_requests (id, org_id, project_id, finding_id, provider, url, state, branch, created_by, source) VALUES ($1,$2,$3,$4,'github',$5,'draft',$6,$7,'sentra_draft')`, [id('pr'), f.org_id, f.project_id, f.id, pr.html_url, branch, ctx.identity.id]);
  await db.query(`INSERT INTO finding_events (id, finding_id, kind, to_value, reason, actor, data) VALUES ($1,$2,'evidence','draft_pr',$3,$4,$5)`, [id('fev'), f.id, `Draft PR opened: ${bump.change}`, ctx.identity.id, { url: pr.html_url, branch }]);
  await audit(db, ctx, 'remediation.draft_pr_created', { targetType: 'finding', targetId: f.id, projectId: f.project_id, data: { url: pr.html_url, branch, change: bump.change } });
  return { url: pr.html_url, number: pr.number, branch, change: bump.change, note: bump.note || null };
}
